function validate([command]) {
  if (typeof command !== 'string' || command.length < 1 || command.length > 100) return 'command needs 1 to 100 characters.';
  if (!/^(G|\(\)|\(al\))+$/.test(command)) return 'command may only contain the tokens "G", "()" and "(al)".';
  return null;
}

reference:
function interpret(command) {
  let result = '';
  let i = 0;

  while (i < command.length) {
    if (command[i] === 'G') {
      result += 'G';
      i += 1;
    } else if (command[i + 1] === ')') {
      result += 'o';
      i += 2;
    } else {
      result += 'al';
      i += 4;
    }
  }
  return result;
}

