function generate(rand, size) {
  const tokens = ['G', '()', '(al)'];
  const limit = size === 'large' ? 90 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 12);
  // Some inputs favour one token so long runs of it appear.
  const favourite = Math.floor(rand() * 3);
  const bias = rand() * 0.7;
  let command = '';
  for (;;) {
    const token = rand() < bias ? tokens[favourite] : tokens[Math.floor(rand() * 3)];
    if (command.length + token.length > limit) break;
    command += token;
  }
  return [command.length > 0 ? command : 'G'];
}
